"""Chapters 4-7: inputs and calibration, maskers, fast model, CASP bridge."""
from refs_aml import *
from pathlib import Path
FIG = Path(__file__).resolve().parent / 'figures'


def ch4(b, D):
    b.chapter('קלטי שמע, כיול ורמות פיזיקליות', 'ch4')
    b.section('הקלט: WAV של לחץ ב-Pa')
    b.para('המטרה נטענת כקובץ WAV חד-ערוצי (ערוץ ראשון, אם יש כמה) בכל תדר דגימה ובכל עומק סיביות. קובץ float נחשב כאילו הערכים שלו הם כבר פסקלים, כפי שמייצאות תוכנות מדידה. לקבצים אחרים נדרש כיול, ויש ארבעה מצבים:')
    b.table(['מצב', 'מה נדרש', 'מה מחושב'], [
        ['pa_float', 'כלום', 'המשרעת היא Pa'],
        ['fullscale_pa', 'לחץ שיא שמתאים ל-1.0 בסקאלה מלאה', 'מקדם $=$ הלחץ הנתון'],
        ['calibrator', 'מקטע של כלי כיול ב-1 kHz ורמתו (94 או 114 dB)', 'סינון 800–1250 Hz, הרמה נקבעת על RMS של המקטע'],
        ['known_level', 'רמה ידועה (Leq או LAeq) של מקטע', 'מקדם שמביא את המקטע לרמה הנתונה'],
    ], caption='מצבי כיול המשרעת', label='tab_cal', widths=[3.2, 6.8, 6.2])
    b.para('בדקנו את ארבעת המצבים באופן אוטומטי: כיול של 94 dB מחזיר ‎94.0 dB בדיוק של פחות מ-0.1 dB, רמה ידועה מושגת בדיוק של 0.01 dB, וכיול סקאלה מלאה נותן שיא של 1 Pa. '
           'הרמות מחושבות כ-$L=20\\lg(p_{\\mathrm{rms}}/20\\,\\mu\\mathrm{Pa})$, ו-LAeq על ידי מסנן FIR לינארי-פאזה שנבנה מהנוסחה האנליטית של IEC 61672-1 ' + cite(IEC61672) + '. '
           'אימתנו את A-weighting מול ערכי הטבלה הנומינליים (למשל ‎−16.1 dB ב-125 Hz ו-‎+1.2 dB ב-2 kHz) בסטייה של עד 0.1 dB.')
    b.section('מרחק מדידה ומרחק מקלט')
    b.para('ברירת המחדל היא מיקרופון ב-7 m. כדי לשחזר את האות במרחק מקלט אחר $d_2$ מנקודה ב-$d_1$ השתמשנו בהתפשטות כדורית ובבליעה אטמוספרית:')
    b.eq(r'L(d_2)=L(d_1)-20\lg\frac{d_2}{d_1}-\alpha(f)\,(d_2-d_1)', 'eq_prop')
    b.para('$\\alpha(f)$ בדציבלים למטר מחושב לפי ISO 9613-1 ' + cite(ISO9613_1) + ' בטמפרטורה ולחות שמוגדרות, ומוחל כמסנן מגניטודה בעל פאזה אפס. אימתנו את הנוסחה מול טבלה 2 של ISO 9613-2:1996 ' + cite(ISO9613_2) + ' ב-20°C ו-70% לחות, בשמונה פסי אוקטבה: '
           'התוצאה מתאימה לערכי הטבלה (0.1, 0.3, 1.1, 2.8, 5.0, 9.0, 22.9, 76.6 dB/km) בתוך עיגול הטבלה. **לא** מוסיפים השפעת קרקע, מחסומים או מזג אוויר; למקרים אלה נדרש כלי חיזוי מלא.')
    b.section('חיסור רעש רקע')
    b.para('כשההקלטה כוללת רעש רקע, מבחינים בין הרעש הכולל לרעש הספציפי של המקור ' + cite(ISO1996_1) + '. המערכת מאפשרת לסמן מקטע רקע בלבד בתוך ההקלטה או לטעון קובץ רקע, ומבצעת חיסור הספק ספקטרלי (STFT עם חלון Hann, 75% חפיפה): '
           '$|X_s|^2=\\max\\left(|X|^2-\\beta\\,|N|^2,\\;g_{\\min}|X|^2\\right)$ כאשר $\\beta$ הוא מקדם החיסור, ו-$g_{\\min}$ רצפה ספקטרלית שמונעת "רעש מוזיקלי". '
           'בכל פס שליש אוקטבה שבו ההפרש בין ההקלטה לרקע קטן מ-3 dB המערכת מזהירה שהתוצאה לא אמינה. זהו אומדן ולא תיקון תקני.')
    b.section('רמת מקלט מול רמת האוזניות')
    b.para('שתי כמויות שונות נדרשות להפרדה. **רמת המקלט** היא הלחץ הפיזי בעמדת המאזין בשטח. **רמת ההשמעה** היא מה שנוצר באוזניות. הקשר ביניהן הוא הכיול של האוזניות (רגישות: dB SPL של סינוס בסקאלה מלאה) ותקרת בטיחות. '
           'אם הרגישות לא נמדדה, הניסוי רץ ברמות נומינליות ומסומן כך. אין פיצוי למעבר בין שדה חופשי לאוזניות; זו הנחה שמצוינת בדוחות.')


def ch5(b, D):
    b.chapter('יצירת מסכים: טבעיים וסינתטיים', 'ch5')
    b.para('כל המסכים נוצרים באופן דטרמיניסטי ביחידות Pa ומתכווננים לרמה נתונה (LAeq או Leq). הם **מודלי אות** של האופי האקוסטי של הצליל (צורת ספקטרום, תנודות בזמן, סטטיסטיקה של אירועים), ולא סימולציות פיזיקליות של המקור. '
           'הם מסומנים SYNTHETIC בכל ייצוא. {ref:fig_maskers} מציג את הספקטרום של שמונת הסוגים באותה רמה, 40 dBA.')
    b.fig(FIG / 'maskers' / 'fig_masker_spectra', 'ספקטרום שליש אוקטבה של המסכים, כולם מכוילים ל-40 dBA במקלט. הצורות שונות מאוד אף שה-LAeq זהה.', 'fig_maskers')
    b.table(['מסכה', 'מודל', 'פרמטרים עיקריים'], [
        ['רעש לבן, ורוד, חום', 'סינתזה ב-FFT עם הספק $\\propto 1/f^{\\beta}$, $\\beta=0,1,2$', 'ללא'],
        ['רוח', 'רעש ורוד-חום מסונן + רעש פס עם גאסטים (לוג-נורמלי)', 'קצב ועומק משבים, רכיב שריקה'],
        ['צרצרים', 'פולסים של נשא ב-4.5 kHz מקובצים ל"צירצורים", כמה פרטים', 'מספר פרטים, פיזור תדר, קצב פולסים'],
        ['מים זורמים', 'ענן פואסוני של תהודות בועה (Minnaert) עם עליית תדר + רעש נמוך', 'צפיפות אירועים, גודל בועות'],
        ['גשם', 'פגיעות טיפות (פרצי רעש קצרים 1.5–9 kHz) על שכבת רקע', 'עוצמת גשם'],
        ['עלים', 'פצפוצים בקצב שעוקב אחרי משבים, 2–10 kHz', 'קצב, משבים'],
    ], caption='מודלי הסינתזה של המסכים', label='tab_gen', widths=[3.2, 8.2, 4.8])
    b.section('עיצוב ספקטרלי ושונות בזמן')
    b.para('עיצוב ספקטרלי נעשה באפס פאזה במרחב התדר: שיפוע (dB/אוקטבה), מסנני חיתוך נמוך וגבוה, והגברות לפי פס שליש אוקטבה עם אינטרפולציה בציר לוגריתמי. שונות בזמן נקבעת על ידי מאפנן לוג-נורמלי בעל הספק ממוצע יחידה (סטיית תקן בדציבלים ותדר מרכזי), ועל ידי אפנון משרעת אופציונלי. '
           'בדקנו שהמסכים מגיעים לרמה המבוקשת בדיוק של 0.05 dB, שהם דטרמיניסטיים, ושהשיפועים של הרעש הוורוד והחום בפסי אוקטבה הם 0 ו-‎−3 dB/אוקטבה כמצופה (ההספק לכל Hz של רעש חום יורד ב-6 dB/אוקטבה, ולכן רמת פס אוקטבה יורדת ב-3 dB).')
    b.section('מטרות סינתטיות')
    b.para('כדי שאפשר יהיה להריץ את המערכת בלי הקלטות, יצרנו ארבע מטרות סינתטיות: הכאה (פגיעות מתכת, 1.8 לשנייה, תהודות ב-1.25–6.9 kHz), קידוח בפטיש (הרמוניות של 95 Hz ופולסי הכאה ב-42 Hz), פטיש אוויר (20 פגיעות לשנייה) ומשחזת. '
           '{ref:fig_targets} מציג אותן. לגורם השיא של ההכאה יש חשיבות מכרעת בפרק 8.')
    b.fig(FIG / 'targets' / 'fig_targets', 'המטרות הסינתטיות: צורת גל של ההכאה וספקטרום ארבע המטרות ב-60 dBA.', 'fig_targets')


def ch6(b, D):
    b.chapter('המודל המהיר ERB-EDM', 'ch6')
    b.para('חיזוי אינטראקטיבי דורש חישוב בעשרות מילישניות, ו-CASP דורש דקות. לכן בנינו מודל מהיר, ERB-EDM, שאינו CASP ואינו מוצג כמודל של CASP. כל שלב במודל נשען על תקדים בספרות, והמודל מכויל פעם אחת בלבד.')
    b.section('שלבי המודל')
    b.bullets([
        '**סינון.** 36 ערוצי גמאטון מסדר 4 בין 50 ל-12,000 Hz, מרווח של ERB אחד. הפלט נמדד כהספק ערוץ $E(k,t)$ ב-Pa² בחלונות $T_k=\\max(10\\,\\mathrm{ms},\\,1.5/\\mathrm{ERB}_k)$ בקפיצה של 5 ms.',
        '**רצפת רעש פנימי.** הספק הטון בסף השמיעה בשקט (קירוב Terhardt ' + cite(TERHARDT) + ') מתחלק ביחס האות לרעש שמוגדר בעוגן הכיול, וכך סף הסוואה וסף בשקט חולקים אותו קבוע.',
        '**הסוואה לאחור בזמן.** הספק המסכה נפרש קדימה בדעיכה מעריכית עם $\\tau=30$ ms ' + cite(JESTEADT) + '.',
        '**גלאי אנרגיה בכל תא זמן-תדר.** תנודות האנרגיה של רעש בחלון $T$ וברוחב $W$ הן בעלות שונות יחסית $1/(TW)$ (חי-בריבוע עם $2TW$ דרגות חופש), ועליה מוסיפים רצפה של $\\varepsilon=0.1$ לרזולוציית הרמה (כ-0.4 dB).',
        '**שילוב.** שילוב אופטימלי בין ערוצים וזמן, וחלון אינטגרציה של 300 ms ' + cite(PLOMP) + '; הגילוי נקבע לפי החלון בעל $d\'$ הגבוה ביותר.',
        '**המרה להסתברות.** $P=\\Phi(d\'/\\sqrt{2})$ ' + cite(GREEN) + '.',
    ], numbered=True)
    b.eq(r"d'^2=\max_t\sum_{k}\sum_{i\in\mathrm{win}}\eta^2\,\frac{\Delta t}{T_k}\;\frac{\left(E_{T}/(E_{M}+E_{\mathrm{int}})\right)^2}{1/(T_kW_k)+\varepsilon^2}", 'eq_dprime')
    b.para('$E_T$ הוא הספק הערוץ של המטרה, $E_M$ של המסכה (אחרי פריסה בזמן), $E_{\\mathrm{int}}$ הרעש הפנימי, $W_k$ רוחב ה-ERB, $\\Delta t$ הקפיצה, ו-$\\eta$ קבוע הכיול. הגורם $\\Delta t/T_k$ מתקן לחפיפה בין חלונות סמוכים.')
    b.section('כיול ועוגן')
    b.para(f'הקבוע $\\eta={D["eta"]:.3f}$ נקבע כך שטון של 500 ms ב-1 kHz ברעש לבן מגיע ל-$P=0.75$ ביחס קריטי של 18 dB ' + cite(HAWKINS) + '. זהו פרמטר חופשי יחיד. כל השאר נגזר מהספרות או נבחר בתחילת העבודה, ואינו מכוון מחדש.')
    b.section('תוצאות הבדיקה העצמית')
    b.para('{ref:fig_fast_val} מציג שלוש תכונות שהמודל אמור לשחזר איכותית ולא רק את העוגן עצמו. (א) היחס הקריטי עולה עם התדר, מ-' + f'{D["cr"][0]:.1f}' + ' ב-250 Hz ל-' + f'{D["cr"][-1]:.1f}' + ' dB ב-8 kHz. '
           '(ב) סף של צליל קצר גבוה מזה של צליל ארוך: מ-20 ms ל-500 ms הסף יורד בכ-' + f'{D["dur_drop"]:.1f}' + ' dB. (ג) הפונקציה הפסיכומטרית עולה מ-0.5 ל-0.99 בתוך כ-12 dB סביב הסף.')
    b.fig(FIG / 'validation' / 'fig_fast_validation', 'בדיקת המודל המהיר: יחס קריטי לפי תדר, אינטגרציה בזמן ופונקציה פסיכומטרית של טון ב-1 kHz ברעש לבן.', 'fig_fast_val')
    b.fig(FIG / 'validation' / 'fig_forward', 'סף בדיקה של 20 ms אחרי הפסקת מסכה, כפונקציה של ההשהיה. הסף יורד עם ההשהיה, כפי שמצופה מהסוואה לאחור בזמן.', 'fig_fwd', width_cm=11)
    b.callout('warning', 'הנתונים המספריים מהספרות על יחס קריטי ועל אינטגרציה בזמן משמשים כאן להשוואה איכותית. לא בדקנו את הערכים מול הטקסטים המלאים, ולכן אנו לא מציגים התאמה כמותית מעבר לעוגן.')
    b.section('מגבלות')
    b.bullets([
        'אין עיבוד מודולציה מפורש. המודל רגיש לתנודות אנרגיה בחלונות של 10 ms ומעלה, ולא לסינון מודולציה של CASP.',
        'שילוב אופטימלי בין כל הערוצים עשוי להיות אופטימי למטרות רחבות סרט במסכה נמוכה, כפי שנראה בהשוואה ל-CASP בפרק הבא.',
        'הערכת האי-ודאות של ±3 dB להסוואה היא הנחה, ולא נמדדה על משתתפים.',
    ])


def ch7(b, D):
    b.chapter('CASP דרך AMT: הגשר ל-MATLAB ואימות', 'ch7')
    b.para('הרצנו את `paulick2024` מתוך AMT 1.6.0 ' + cite(AMT, PAULICK) + ' ב-MATLAB R2023a (נבדק שהכלים Signal Processing ו-Statistics נמצאים ברישיון). בצד פייתון מכינים גירויים מכוילים, שומרים אותם ל-MAT, מפעילים `matlab -batch` וקוראים JSON. '
           'שום שלב של CASP לא ממומש מחדש בפייתון.')
    b.section('מה בדיוק ממומש')
    b.para('מחקר החומר של AMT חשף ששלב ההחלטה שבהפצה נועד לגילוי הפרשי עוצמה (ב-`demo_paulick2024`), ולא להסוואה על ידי רעש. לכן יישמנו את אותו עקרון: '
           '(1) **תבנית** היא הייצוג הפנימי של מטרה ברמה על-סף ועוד מסכה, פחות המסכה לבדה, ממוצע על כמה מימושי רעש; '
           '(2) **אזור עניין** של ערוצים נבחר מפלט שלב ההסתגלות (`paulick2024_roi`); '
           '(3) כל מרווח נבדק על ידי **מתאם** עם התבנית, אחרי חיסור ייצוג המסכה הממוצע (leave-one-out, כך שהמרווח הנבדק אינו כלול בממוצע); '
           '(4) מרווח של מסכה בלבד נוצר ממימוש רעש אחר; '
           '(5) `paulick2024_decision` ממפה את המתאם ל-$P=\\Phi(0.707\\,\\mu/\\sigma)$, ו-$\\sigma^2$ הוא השונות הפנימית.')
    b.section('כיול השונות הפנימית')
    b.para(f'עם השונות של AMT ($\\sigma^2=40$) קיבלנו ש-CASP היה רגיש מאוד: בבדיקה ב-4 kHz סף הגילוי (P=0.75) התקבל בהסטת רעש של {D["raw4"]:.1f} dB, לעומת {D["fast4"]:.1f} dB במודל המהיר, כלומר הסטה של יותר מ-10 dB ביחס למודל המהיר שכויל לאותו עוגן (ראו קו מנוקד באיור). '
           f'כיילנו את $\\sigma^2$ מחדש ל-**{D["invar"]:.0f}**, כך שאותו עוגן (טון של 500 ms ב-1 kHz ברעש לבן ביחס קריטי של 18 dB) יתן $P=0.75$. חזית המודל לא שונתה, והדוחות מציגים גם את הגרסה הגולמית וגם את המכוילת.')
    b.callout('warning', 'שלב ההחלטה לרעש הוא **הרחבה של AMT**, לא חלק ממנו. שחזור הניסוי של Paulick ואחרים ' + cite(PAULICK) + ' בניסויי הסוואה הוא מחוץ לטווח העבודה. אנו מדווחים אותו כגשר מכויל ולא כ"תוצאת CASP" טהורה.')
    b.section('תוצאות האימות')
    b.fig(FIG / 'validation' / 'fig_casp_vs_fast', 'CASP (מכויל וגולמי) מול המודל המהיר, טון ב-1 kHz (עוגן הכיול) וב-4 kHz (בדיקה בלתי תלויה), ברעש לבן.', 'fig_casp')
    b.table(['תרחיש', 'סף CASP מכויל', 'סף ERB-EDM', 'הפרש'], [
        ['טון 1 kHz (עוגן)', 'עוגן', 'עוגן', '—'],
        ['טון 4 kHz', f'{D["casp4"]:.1f} dB', f'{D["fast4"]:.1f} dB', f'{D["casp4_diff"]:.1f} dB'],
    ], caption='הסף כהסטת רמת רעש (dB) שבה P=0.75, ב-4 kHz', label='tab_casp', widths=[4.4, 4.0, 4.0, 3.8])
    b.para(f'בבדיקה הבלתי תלויה ב-4 kHz, CASP רגיש יותר ב-{D["casp4_diff"]:.1f} dB, והעקומה הפסיכומטרית שלו שטוחה בהרבה (עלייה של 0.53 ל-0.76 על פני 24 dB, לעומת 12 dB במודל המהיר). '
           'יש שתי משמעויות. ראשית, אי-הוודאות של ±3 dB שהגדרנו למודל המהיר אופטימית. שנית, ההבדל בשיפוע אומר שבהסתברויות גילוי נמוכות (קרוב ל-0.5) המודלים נבדלים יותר מבסף עצמו. נשתמש בשני המודלים כמסגרת לטווח סביר, ולא כשני אומדנים של אותה כמות.')
    b.para('הרצת CASP לגירוי של 0.5 s עם 5 מימושי רעש ו-5 רמות לוקחת כמה דקות, וזמן זה גדל עם אורך הקטע ומספר המסכים. הממשק מציג התקדמות ומאפשר ביטול.')
